// Run: node day48/debug/async-bugs.js
const db = { 1: { id: 1, name: 'Asha' }, 2: { id: 2, name: 'Ravi' }, 3: { id: 3, name: 'Meena' } };

function fetchUser(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (db[id]) resolve(db[id]);
      else reject(new Error(`User ${id} not found`));
    }, 100 * Math.random());
  });
}

// 1. Print one user's name. Expect: name: Asha
async function printName(id) {
  const user = fetchUser(id);
  console.log('name:', user.name);
}

// 2. Load users in order. Expect: [ 'Asha', 'Ravi', 'Meena' ]
async function loadAll(ids) {
  const names = [];
  ids.forEach(async (id) => {
    const u = await fetchUser(id);
    names.push(u.name);
  });
  return names;
}

// 3. A missing user gives a friendly message. Expect: Could not load user 99
async function safeLoad(id) {
  try {
    return fetchUser(id);
  } catch (err) {
    return `Could not load user ${id}`;
  }
}

// 4. Wait about 1 second
function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve(), ms));
}

async function main() {
  await printName(1);
  console.log('all:', await loadAll([1, 2, 3]));
  console.log('safe:', await safeLoad(99));
  const start = Date.now();
  await wait(1000);
  console.log('waited ms ≥ 1000?', Date.now() - start >= 1000);
}

main();
